import {
  appAssetsFileSchema,
  assetColor,
  contractAssetsFileSchema,
  displaySymbol,
  indexerWhitelistsSchema,
  loadAssets,
  loadProfile,
  parseConfig,
  toE18,
  TODO,
  type AppAsset,
  type Asset,
  type ContractAsset,
  type ContractAssetsFile,
  type IndexerWhitelists,
  type AppAssetsFile,
  type Profile,
  type ProfileName,
} from "@pantado/shared";

export const GENERATED_NOTE =
  "GENERATED by scripts/gen-config.ts from config/assets.json — do not edit; run `pnpm gen:config`.";

export const PROFILES: readonly ProfileName[] = ["contest", "production"];

export const OUTPUT = {
  contractAssets: (network: string): string => `contracts/config/assets.${network}.json`,
  indexerWhitelists: "services/indexer/generated/whitelists.json",
  appAssets: "apps/web/generated/assets.json",
  dexRoutes: (network: string): string => `contracts/config/dex-routes.${network}.json`,
} as const;

/** DexVenue hop kinds (contracts/src/venues/DexVenue.sol `Kind`). */
const HOP_KIND = { univ2: 0, solidly: 1, "liquidity-book": 2 } as const;

export interface DexRoute {
  asset: string;
  token: string;
  pools: string[];
  kinds: number[];
  fees: number[];
}

/**
 * `execution.dexRoutes` → what the deploy script hands to DexVenue.setRoute. Each route is checked here: every pool
 * is a confirmed data.avalanche pool (uniswap-v2 with `amm`, or liquidity-book), and the pools chain the asset to the
 * quote token. Null when the profile has no DEX routes.
 */
export function dexRoutesFile(assets: Asset[], profile: Profile): { $comment: string; network: string; routes: DexRoute[] } | null {
  const routes = profile.execution.dexRoutes;
  if (!routes) return null;
  const pools = new Map((profile.data.avalanche.pools ?? []).map((p) => [p.address.toLowerCase(), p]));
  const byId = new Map(assets.map((a) => [a.id, a]));
  const out: DexRoute[] = [];
  for (const [id, path] of Object.entries(routes).sort(([a], [b]) => a.localeCompare(b))) {
    const a = byId.get(id);
    if (!a || a.kind !== "token") throw new Error(`dexRoutes.${id}: not a listed token`);
    const token = executionAddress(a, profile);
    if (!isAddress(token)) throw new Error(`dexRoutes.${id}: execution address not confirmed`);
    let cur = id;
    const kinds: number[] = [];
    const fees: number[] = [];
    for (const addr of path) {
      const p = pools.get(addr.toLowerCase());
      if (!p || !p.confirmed) throw new Error(`dexRoutes.${id}: pool ${addr} is not a confirmed data pool`);
      if (p.token0 !== cur && p.token1 !== cur) throw new Error(`dexRoutes.${id}: pool ${addr} does not hold ${cur}`);
      cur = p.token0 === cur ? p.token1 : p.token0;
      if (p.dex === "liquidity-book") {
        kinds.push(HOP_KIND["liquidity-book"]);
        fees.push(0);
      } else if (p.dex === "uniswap-v2" && p.amm) {
        if (p.amm === "univ2" && !p.feeBps) throw new Error(`dexRoutes.${id}: univ2 pool ${addr} needs feeBps`);
        kinds.push(HOP_KIND[p.amm]);
        fees.push(p.amm === "univ2" ? (p.feeBps ?? 0) : 0);
      } else throw new Error(`dexRoutes.${id}: pool ${addr} (${p.dex}) has no on-chain quote for the DEX venue`);
    }
    if (cur !== profile.execution.quote) throw new Error(`dexRoutes.${id}: route ends in ${cur}, not ${profile.execution.quote}`);
    out.push({ asset: id, token, pools: path, kinds, fees });
  }
  return { $comment: GENERATED_NOTE, network: profile.execution.network, routes: out };
}

function isAddress(v: string | null | undefined): v is `0x${string}` {
  return typeof v === "string" && /^0x[0-9a-fA-F]{40}$/.test(v);
}

/** Execution address of an asset on the profile's execution network. */
function executionAddress(a: Asset, profile: Profile): string {
  if (a.kind === "stock") return "deploy"; // pTokens are always deployed by the stock venue
  if (profile.execution.network === "fuji" || profile.execution.network === "anvil") {
    const f = a.execution.fuji.address;
    return f === "deploy" ? "deploy" : f;
  }
  const m = a.execution.avalanche;
  return m.confirmed === true && isAddress(m.address) ? m.address : TODO;
}

export function contractAsset(a: Asset, profile: Profile): ContractAsset {
  const isTestNet = profile.execution.network !== "avalanche";
  const price = a.price.canonical === "fixed" ? a.price.fixedUsd : a.price.seedUsd;
  if (price === undefined) throw new Error(`${a.id}: no seed price`);
  return {
    addr: executionAddress(a, profile) as ContractAsset["addr"],
    bandMaxE18: toE18(a.price.bandMaxUsd).toString(),
    bandMinE18: toE18(a.price.bandMinUsd).toString(),
    decimals: a.decimals,
    id: a.id,
    kind: a.kind,
    maxAgeSec: a.price.maxAgeSec,
    mock: isTestNet && a.kind !== "stock" && a.execution.fuji.mock === true,
    name: a.kind === "stock" ? `Pantado ${a.name}` : a.name,
    oiCapUsd: a.kind === "stock" ? a.risk.oiCapUsd : 0,
    pTokenName: a.kind === "stock" ? `Pantado ${a.name}` : "",
    pTokenSymbol: a.kind === "stock" ? `p${a.symbol}` : "",
    priceE18: toE18(price).toString(),
    sizeCapUsd: a.kind === "stock" ? a.risk.sizeCapUsd : 0,
    spreadBps: a.kind === "quote" ? 0 : a.risk.spreadBps,
    symbol: a.kind === "stock" ? `p${a.symbol}` : a.symbol,
    tier: a.kind === "stock" ? a.tier : 0,
    venue: a.venue[profile.profile] ?? "none",
  };
}

export function contractAssetsFile(assets: Asset[], profile: Profile): ContractAssetsFile {
  return parseConfig(
    contractAssetsFileSchema,
    {
      $comment: GENERATED_NOTE,
      network: profile.execution.network,
      chainId: profile.execution.chainId,
      profile: profile.profile,
      quote: profile.execution.quote,
      // quote first so deploy scripts can rely on index 0
      assets: [...assets]
        .sort((x, y) => Number(y.kind === "quote") - Number(x.kind === "quote"))
        .map((a) => contractAsset(a, profile)),
    },
    OUTPUT.contractAssets(profile.execution.network),
  );
}

export function indexerWhitelists(assets: Asset[], contest: Profile): IndexerWhitelists {
  const tokens: IndexerWhitelists["avalanche"]["tokens"] = [];
  const stocks: IndexerWhitelists["robinhood"]["stocks"] = [];
  const pendingAvax: string[] = [];
  const pendingRh: string[] = [];
  for (const a of assets) {
    if (a.kind === "stock") {
      const d = a.display;
      if (d.confirmed && isAddress(d.token) && isAddress(d.referencePool))
        stocks.push({ id: a.id, symbol: a.symbol, token: d.token, referencePool: d.referencePool });
      else pendingRh.push(a.id);
    } else {
      const d = a.display;
      if (d.confirmed && isAddress(d.address))
        tokens.push({ id: a.id, symbol: a.symbol, address: d.address, decimals: a.decimals });
      else pendingAvax.push(a.id);
    }
  }
  return parseConfig(
    indexerWhitelistsSchema,
    {
      $comment: `${GENERATED_NOTE} Only confirmed addresses are whitelisted; 'pending' lists ids awaiting verification.`,
      avalanche: { chainId: contest.data.avalanche.chainId, tokens, pending: pendingAvax },
      robinhood: { chainId: contest.data.robinhood.chainId, stocks, pending: pendingRh },
      execution: assets.map((a) => ({
        id: a.id,
        symbol: a.kind === "stock" ? `p${a.symbol}` : a.symbol,
        kind: a.kind,
      })),
    },
    OUTPUT.indexerWhitelists,
  );
}

export function appAsset(a: Asset): AppAsset {
  const confirmedAddr =
    a.kind === "stock"
      ? a.display.confirmed && isAddress(a.display.token)
        ? a.display.token
        : null
      : a.display.confirmed && isAddress(a.display.address)
        ? a.display.address
        : null;
  return {
    id: a.id,
    symbol: a.symbol,
    displaySymbol: displaySymbol(a.symbol),
    name: a.name,
    kind: a.kind,
    tier: a.kind === "stock" ? a.tier : null,
    decimals: a.decimals,
    displayChain: a.display.chain,
    displayAddress: confirmedAddr,
    badge: a.kind === "stock" ? a.display.badge : null,
    logoURI: a.logoURI,
    color: assetColor(a.id),
    sizeCapUsd: a.kind === "stock" ? a.risk.sizeCapUsd : null,
    venue: { contest: a.venue.contest, production: a.venue.production },
  };
}

export function appAssetsFile(assets: Asset[]): AppAssetsFile {
  return parseConfig(
    appAssetsFileSchema,
    { $comment: GENERATED_NOTE, assets: assets.map(appAsset) },
    OUTPUT.appAssets,
  );
}

/** Every generated file as `relative path → JSON text`. Pure apart from reading config. */
export function generateAll(root?: string): Map<string, string> {
  const opts = root ? { root } : {};
  const assets = loadAssets(opts);
  const profiles = PROFILES.map((p) => loadProfile(p, opts));
  const out = new Map<string, string>();
  const json = (v: unknown): string => `${JSON.stringify(v, null, 2)}\n`;
  for (const profile of profiles) {
    out.set(OUTPUT.contractAssets(profile.execution.network), json(contractAssetsFile(assets, profile)));
    const routes = dexRoutesFile(assets, profile);
    if (routes) out.set(OUTPUT.dexRoutes(profile.execution.network), json(routes));
  }
  const contest = profiles.find((p) => p.profile === "contest");
  if (!contest) throw new Error("contest profile missing");
  out.set(OUTPUT.indexerWhitelists, json(indexerWhitelists(assets, contest)));
  out.set(OUTPUT.appAssets, json(appAssetsFile(assets)));
  return out;
}
